function Rj([string]$p){Get-Content -Raw $p|ConvertFrom-Json}
function Wj([string]$p,$v){New-Item -ItemType Directory -Force (Split-Path $p)|Out-Null;[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 100)+[Environment]::NewLine,[Text.UTF8Encoding]::new($false))}
function Wt([string]$p,[string]$v){New-Item -ItemType Directory -Force (Split-Path $p)|Out-Null;[IO.File]::WriteAllText($p,$v.Trim()+[Environment]::NewLine,[Text.UTF8Encoding]::new($false))}
function Sha([string]$p){(Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function Rel([string]$p){(Resolve-Path $p).Path.Substring($repo.Length+1).Replace('\','/')}
function N([string]$s){(($s -replace '\s+',' ').Trim())}
function IN([string]$s){(N $s).ToLowerInvariant()}
function PN([string]$s){((IN $s)-replace '[^\p{L}\p{Nd}]+','')}

