 foreach($doc in $docOrder){$rel=$sources[$doc];$path=Join-Path $repo ($rel-replace '/','\');if(-not(Test-Path $path)){throw "Missing source $doc $rel"};$sha=Sha $path;$rows=@(Read-Rows $path);$hits=@(Get-Headings $doc $rows);$bindings=[Collections.Generic.List[object]]::new();$ord=0;foreach($h in $hits){$ord++;$bindings.Add([ordered]@{occurrenceId="$doc`:$($h.row.sourceId)#heading-span-$($h.start)-$($h.end)";documentId=$doc;sourceOccurrenceId="$doc`:$($h.row.sourceId)";sourceId=$h.row.sourceId;sourceSpan=[ordered]@{start=$h.start;end=$h.end};exactText=$h.text;headingKind=$h.kind;documentOrder=$h.row.documentOrder;occurrenceOrder=$ord;sourceContainerText=$h.row.rawText;sourceContainerKind=$h.row.containerKind;structuralScopeType=if($h.row.inTable){'TABLE_OR_EMBEDDED_SCOPE'}elseif($h.text-match'(?i)annex|appendix|schedule|form|template'){ 'DOCUMENT_SUBSCOPE'}else{'MAIN_BODY_OR_DOCUMENT_OUTLINE'};isTrueHeading=$true;sourceEvidence=[ordered]@{style=$h.row.style;outlineLevel=$h.row.level;bold=$h.row.bold;caps=$h.row.caps;alignment=$h.row.alignment;parserOwnedEvidenceOnly=$true};adjudicationEvidence=@($h.evidence);adjudicationProvenance='AGENT_SOURCE_BACKED_ADJUDICATION'})}
