  $id=Build-Identity $doc $bindings $hits;$h=Build-Hierarchy $doc $id.nodes $id.assignments $bindings;$resetAudit.Add([ordered]@{documentId=$doc;invariant='NO_PARENT_MAY_CROSS_AN_INTERVENING_STRUCTURAL_RESET';scopeStackUsed=$true;violations=@($h.errors|Where-Object{$_-match'DANGLING|CYCLE'});changedEdges=@();status=if($h.errors.Count-eq 0){'PASS'}else{'FAIL'}});$identityAudit.Add([ordered]@{documentId=$doc;occurrenceCount=$bindings.Count;semanticNodeCount=$id.nodes.Count;primary=@($id.assignments|Where-Object {$_.occurrenceRole -eq 'PRIMARY'}).Count;repeat=@($id.assignments|Where-Object {$_.occurrenceRole -eq 'REPEAT'}).Count;continuation=@($id.assignments|Where-Object {$_.occurrenceRole -eq 'CONTINUATION'}).Count;lexicalCollisionCandidates=@($id.challenges|Where-Object {$_.candidateType -eq 'LEXICAL_COLLISION'}).Count;structuralAdjacencyCandidates=@($id.challenges|Where-Object {$_.candidateType -eq 'STRUCTURAL_ADJACENCY'}).Count;acceptedRelations=$id.relations;challengeCases=$id.challenges})
