  Wj (Join-Path $idDir 'identity-decisions.json') ([ordered]@{artifactKind='A99_CANONICAL_V3_2_IDENTITY_DECISIONS';documentId=$doc;occurrenceCount=$bindings.Count;semanticNodeCount=$id.nodes.Count;assignments=$id.assignments;relations=$id.relations;challengeCases=$id.challenges;reviewAuthority='AGENT_SOURCE_BACKED_ADJUDICATION';goldUsed=$false;historicalLevelRead=$false})
