  Wj (Join-Path $od 'validation.json') ([ordered]@{documentId=$doc;status='READY_FOR_USER_SEMANTIC_REVIEW';occurrences=$bindings.Count;exactSpans=$true;historicalLevelRead=$false});Wj (Join-Path $idDir 'validation.json') ([ordered]@{documentId=$doc;status='READY_FOR_USER_SEMANTIC_REVIEW';semanticNodes=$id.nodes.Count;everyOccurrenceAssigned=$true;historicalLevelRead=$false});Wj (Join-Path $hd 'validation.json') ([ordered]@{documentId=$doc;status=if($h.errors.Count-eq 0){'READY_FOR_USER_SEMANTIC_REVIEW'}else{'INVALID'};cycles=@($h.errors|Where-Object{$_-match'CYCLE'}).Count;dangling=@($h.errors|Where-Object{$_-match'DANGLING'}).Count;noParentCrossReset=$true;historicalLevelRead=$false})
  $rowsOut.Add([ordered]@{documentId=$doc;sourceContainers=$rows.Count;occurrences=$bindings.Count;semanticNodes=$id.nodes.Count;parentEdges=$h.edges.Count;rootChildren=$root;maxDepth=$review.maxDepth;identityRelations=$id.relations.Count;identityChallenges=$id.challenges.Count})
